import{at as e,it as t,n,vt as r}from"./chunks/framework.DbV_8hbX.js";var i=JSON.parse(`{"title":"Preview and verification","description":"","frontmatter":{},"headers":[],"relativePath":"en/guides/testing.md","filePath":"en/guides/testing.md","lastUpdated":1794405696000}`),a={name:`en/guides/testing.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="preview-and-verification" tabindex="-1">Preview and verification <a class="header-anchor" href="#preview-and-verification" aria-label="Permalink to “Preview and verification”">​</a></h1><h2 id="three-ways-to-check" tabindex="-1">Three ways to check <a class="header-anchor" href="#three-ways-to-check" aria-label="Permalink to “Three ways to check”">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Purpose</th></tr></thead><tbody><tr><td>The display image in the admin console</td><td>Check the look while you type</td></tr><tr><td>Preview in the campaign list</td><td>Force a one-time display on a real page</td></tr><tr><td>The diagnostic panel for verification</td><td>Observe normal measurement, sending and decisions</td></tr></tbody></table><p>The Cloudflare Preview used to update the system is <a href="./../getting-started/preview-production">a feature for checking a separate environment</a>.</p><h2 id="show-a-check-display-on-a-real-page" tabindex="-1">Show a check display on a real page <a class="header-anchor" href="#show-a-check-display-on-a-real-page" aria-label="Permalink to “Show a check display on a real page”">​</a></h2><ol><li>Save the content as a draft.</li><li>Press &quot;Preview (「プレビュー」)&quot; in the campaign list.</li><li>Enter the page URL you want to check.</li><li>Press &quot;Open page and check (「ページを開いて確認」)&quot;, and keep the admin console open too.</li></ol><p>A saved draft takes priority, and without one the saved delivery content is used. Unsaved edits are not included. You can also check campaigns that are stopped or not yet in normal delivery.</p><h2 id="url-conditions" tabindex="-1">URL conditions <a class="header-anchor" href="#url-conditions" aria-label="Permalink to “URL conditions”">​</a></h2><p>The URL must match the site&#39;s registered origin, the collected or excluded paths, and the campaign&#39;s display targets. For example, you can&#39;t check a campaign with an exact match of <code>/ja/</code> on <code>/ja/products/a</code>.</p><p>The target page needs the latest SDK. If a CMP prevents the SDK itself from loading, you can&#39;t start it. It is not a mechanism that rewrites your site&#39;s HTML or injects the tag automatically.</p><h2 id="the-one-time-mechanism" tabindex="-1">The one-time mechanism <a class="header-anchor" href="#the-one-time-mechanism" aria-label="Permalink to “The one-time mechanism”">​</a></h2><p>A check ticket is valid for 5 minutes and works once. It is handed from the admin console to the tab you just opened and shows the specified campaign. The ticket itself is not stored in the page URL or in Web Storage.</p><p>During a check, normal measurement and automatic decisions are paused. It doesn&#39;t call Jev, and it doesn&#39;t update the normal history, display count or closed state. The page also indicates that it is a check display.</p><p>It ends when you close it or navigate away. A copy of the same URL or a reload doesn&#39;t carry the forced display over. If, after a reload, the conditions are met and normal delivery happens, that is separate behavior.</p><h2 id="if-it-wasn-t-displayed" tabindex="-1">If it wasn&#39;t displayed <a class="header-anchor" href="#if-it-wasn-t-displayed" aria-label="Permalink to “If it wasn&#39;t displayed”">​</a></h2><p>Check for an expired ticket, changed settings, changed permissions, CSP, images, pop-up restrictions, COOP and so on. If rendering fails after the ticket is redeemed, it is still used up, so start a new preview.</p><p>Checking custom JavaScript is limited to admins and above. Authors should suppress custom measurement or updates in preview mode.</p><h2 id="final-check-of-delivery" tabindex="-1">Final check of delivery <a class="header-anchor" href="#final-check-of-delivery" aria-label="Permalink to “Final check of delivery”">​</a></h2><p>Even if a forced display succeeds, it doesn&#39;t verify that the audience judgment is correct. Normal delivery goes through consent, valid views, confirmed conditions, Jev&#39;s score, the threshold and display constraints. Also check the normal flow in the <a href="./debugging">diagnostic panel</a>.</p><h2 id="check-how-page-information-is-fetched" tabindex="-1">Check how page information is fetched <a class="header-anchor" href="#check-how-page-information-is-fetched" aria-label="Permalink to “Check how page information is fetched”">​</a></h2><p>If you want to check which page name and description are fetched, not how the offer looks, use <a href="./sites#fetching-page-information-and-checking-on-a-real-page">Site settings → Page information fetching</a>. Enter a URL and check a draft of the settings, unsaved, with the SDK on the real page. This check doesn&#39;t perform Jev judgment or offer display.</p><h2 id="try-only-how-conditions-combine" tabindex="-1">Try only how conditions combine <a class="header-anchor" href="#try-only-how-conditions-combine" aria-label="Permalink to “Try only how conditions combine”">​</a></h2><p>With &quot;Test these settings (「この設定を試す」)&quot; in campaign editing, you can check the AND/OR result from URL conditions and provisional Jev scores. It doesn&#39;t call the Jev API. Use this test to confirm the conditions are connected correctly, the diagnostic panel for the actual inference in normal delivery, and the real-page preview for the look. For details, see <a href="./campaigns#connect-conditions">connect conditions</a>.</p>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};